const items = $input.all();

if (!items || items.length === 0) {
  throw new Error('No data received from Google Sheets. Check the sheet ID and permissions.');
}

// URL slug from the topic: lower case, words joined by hyphens, at most 60
// characters and always cut on a word boundary (never "...-goi" or "...-commun").
function slugify(text, max = 60) {
  const full = String(text)
    .toLowerCase()
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '') // café -> cafe
    .replace(/['\u2019]/g, '')                          // owner's -> owners
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  if (full.length <= max) return full;
  // Look one character past the limit: if it is a hyphen, the cut is already on a boundary.
  const head = full.slice(0, max + 1);
  const lastHyphen = head.lastIndexOf('-');
  const cut = lastHyphen > 0 ? head.slice(0, lastHyphen) : full.slice(0, max);
  return cut.replace(/-+$/, '');
}

for (let i = 0; i < items.length; i++) {
  const row = items[i].json;
  const allKeys = Object.keys(row).filter(k => k !== 'row_number');
  // Optional "Format" column (any position, any case). Empty or missing: the
  // workflow suggests a format itself (see "Collect Existing Posts").
  const formatKey = allKeys.find(k => /^\s*format\s*$/i.test(k)) || null;
  // Topic, status and date columns are read by position (A, B, C), skipping the format column.
  const keys = allKeys.filter(k => k !== formatKey);
  const colA = keys[0];
  const colB = keys[1];
  const colC = keys.length > 2 ? keys[2] : null;

  if (colB && row[colB] && row[colB].toString().toLowerCase().trim() === 'pending' && row[colA] && row[colA].toString().trim()) {
    // Kept exactly as in the sheet: the sheet update matches the row by this value.
    const topic = row[colA].toString();
    const topicSlug = slugify(topic);
    const format = formatKey && row[formatKey] != null ? row[formatKey].toString().trim() : '';

    return [{
      json: {
        topic,
        rowNumber: row.row_number || (i + 2),
        topicSlug,
        format,
        colA,
        colB,
        colC
      }
    }];
  }
}

throw new Error('No pending topics found in the Google Sheet.');

// Step 2 of 2: combines the two Gemini answers into structured data:
// `frontmatter` (one object, English + Arabic fields) and `body`
// (English, <!-- AR -->, Arabic). The file itself is written later by
// "Quality Gate", so quoting and escaping are done in one place.
const arRaw = $input.first().json.text;
if (!arRaw || !String(arRaw).trim()) {
  throw new Error('No content received from Gemini (Arabic article). Check the AI model response.');
}
const enRaw = $('Check English Draft').first().json.englishDraft;
const topicData = $('Find First Pending Topic').first().json;

// ---- 1. Remove code fences and any chatter before the frontmatter ----
function unwrap(raw) {
  let text = String(raw || '').replace(/\r\n/g, '\n').trim();
  text = text.replace(/^```[a-zA-Z]*[ \t]*\n/, '').replace(/\n```[ \t]*$/, '').trim();
  const fmStart = text.search(/^---[ \t]*$/m);
  if (fmStart > 0) text = text.slice(fmStart);
  return text;
}

// ---- 2. Parse a frontmatter block line by line ----
// Values are read leniently (Gemini sometimes forgets quotes or escapes);
// they are written back strictly by "Quality Gate".
function parseValue(v) {
  v = v.trim();
  if (v.startsWith('[')) {
    try { const a = JSON.parse(v); if (Array.isArray(a)) return a.map(x => String(x).trim()).filter(Boolean); } catch (e) {}
    return v.replace(/^\[|\]$/g, '').split(',').map(s => s.trim().replace(/^["']|["']$/g, '').trim()).filter(Boolean);
  }
  if (v.length >= 2 && v.startsWith('"') && v.endsWith('"')) {
    try { return String(JSON.parse(v)); } catch (e) {}
    return v.slice(1, -1).replace(/\\"/g, '"'); // e.g. "The "Best" Way" with unescaped inner quotes
  }
  if (v.length >= 2 && v.startsWith("'") && v.endsWith("'")) return v.slice(1, -1).replace(/''/g, "'");
  return v;
}
function parse(text, label, parseProblems) {
  const frontmatter = {};
  let body = text;
  const fm = text.match(/^---[ \t]*\n([\s\S]*?)\n---[ \t]*(?:\n|$)/);
  if (!fm) {
    parseProblems.push(label + ': no frontmatter block found at the top of the output');
    return { frontmatter, body };
  }
  body = text.slice(fm[0].length);
  let listKey = null; // for YAML block lists ("tags:" followed by "- a" lines)
  for (const line of fm[1].split('\n')) {
    if (!line.trim()) continue;
    const item = line.match(/^\s*-\s+(.*)$/);
    if (item && listKey) { frontmatter[listKey].push(String(parseValue(item[1]))); continue; }
    const m = line.match(/^([A-Za-z][\w-]*)\s*:\s*(.*)$/);
    if (!m) { parseProblems.push(label + ': unreadable frontmatter line: ' + line.trim().slice(0, 60)); continue; }
    listKey = null;
    if (m[2].trim() === '') { frontmatter[m[1]] = []; listKey = m[1]; continue; }
    frontmatter[m[1]] = parseValue(m[2]);
  }
  return { frontmatter, body };
}

const parseProblems = [];
const en = parse(unwrap(enRaw), 'English', parseProblems);
const ar = parse(unwrap(arRaw), 'Arabic', parseProblems);

// ---- 3. One frontmatter: English fields from step 1, Arabic fields from step 2 ----
const EN_KEYS = ['title', 'metaTitle', 'metaDescription', 'primaryKeyword', 'excerpt', 'tags'];
const AR_KEYS = ['titleAr', 'metaTitleAr', 'metaDescriptionAr', 'excerptAr', 'tagsAr'];
const KNOWN_KEYS = EN_KEYS.concat(AR_KEYS, ['date', 'author', 'authorAr', 'coverImage', 'coverImageAlt',
  'coverImageCredit', 'coverImageCreditUrl', 'category', 'categoryAr']);
const frontmatter = {};
for (const k of EN_KEYS) if (en.frontmatter[k] !== undefined) frontmatter[k] = en.frontmatter[k];
for (const k of AR_KEYS) {
  // The Arabic step sometimes drops the "Ar" suffix (title: "...").
  const v = ar.frontmatter[k] !== undefined ? ar.frontmatter[k] : ar.frontmatter[k.replace(/Ar$/, '')];
  if (v !== undefined) frontmatter[k] = v;
}
const droppedKeys = [
  ...Object.keys(en.frontmatter).filter(k => !KNOWN_KEYS.includes(k)),
  ...Object.keys(ar.frontmatter).filter(k => !KNOWN_KEYS.includes(k) && !EN_KEYS.includes(k))
]; // e.g. a made-up "coverImageAr"
for (const k of Object.keys(frontmatter)) {
  if (typeof frontmatter[k] === 'string') frontmatter[k] = frontmatter[k].replace(/\s+/g, ' ').trim();
}

// ---- 4. Values the workflow decides itself (not left to Gemini) ----
Object.assign(frontmatter, {
  date: $now.toFormat('yyyy-MM-dd'),
  author: 'Accez Team',
  authorAr: 'فريق أكسيز',
  coverImage: '/images/blog/pm-default.jpg',
  coverImageAlt: 'A row of suburban houses under a clear blue sky',
  category: 'Industry Insights',
  categoryAr: 'رؤى الصناعة'
});

// Keep the topic's colon. Titles were losing it ("Sustainability and Energy
// Efficiency Cutting Costs..."): if Gemini returned the topic minus its colon,
// use the topic as written in the sheet.
const flat = s => String(s || '').toLowerCase().replace(/[:\s]+/g, ' ').trim();
if (topicData.topic.includes(':') && frontmatter.title && !frontmatter.title.includes(':')
    && flat(frontmatter.title) === flat(topicData.topic)) {
  frontmatter.title = topicData.topic.trim();
}

// Search titles: fall back to the article title when Gemini's is over 60 characters.
if (frontmatter.metaTitle && frontmatter.metaTitle.length > 60 && frontmatter.title && frontmatter.title.length <= 60) {
  frontmatter.metaTitle = frontmatter.title;
}
if (frontmatter.metaTitleAr && frontmatter.metaTitleAr.length > 60 && frontmatter.titleAr && frontmatter.titleAr.length <= 60) {
  frontmatter.metaTitleAr = frontmatter.titleAr;
}

// Search descriptions over 155 characters: drop whole trailing sentences
// ("Learn more.") while that keeps at least 100 characters. Never cuts mid-sentence.
function trimDescription(s, max = 155, min = 100) {
  let out = String(s || '').trim();
  while (out.length > max) {
    const m = out.match(/^([\s\S]*[.!?؟])\s+[^.!?؟]+[.!?؟]?$/);
    if (!m || m[1].trim().length < min) break;
    out = m[1].trim();
  }
  return out;
}
if (frontmatter.metaDescription) frontmatter.metaDescription = trimDescription(frontmatter.metaDescription);
if (frontmatter.metaDescriptionAr) frontmatter.metaDescriptionAr = trimDescription(frontmatter.metaDescriptionAr);

// ---- 5. Bodies ----
const MARKER = /<!--\s*ar\s*-->/i;
let enBody = en.body.trim();
if (MARKER.test(enBody)) enBody = enBody.split(MARKER)[0].trim(); // step 1 wrote Arabic too: ignore it
let arBody = ar.body.trim();
if (MARKER.test(arBody)) arBody = arBody.split(MARKER).pop().trim(); // step 2 echoed the English first
// Gemini sometimes repeats a (translated) frontmatter block at the top of the body.
arBody = arBody.replace(/^---[ \t]*\n(?:[A-Za-z][\w-]*[ \t]*:.*\n|[ \t]*-[ \t].*\n|[ \t]*\n)+---[ \t]*(?:\n|$)/, '').trim();

// Arabic closing headings must be exactly these (the site and the brief use them verbatim).
arBody = arBody
  .replace(/^#{2,3}[ \t]+(?:ال)?أسئلة[ \t]+(?:ال)?(?:شائعة|متكررة)[ \t]*[:.]?[ \t]*$/gm, '## الأسئلة الشائعة')
  .replace(/^#{2,3}[ \t]+(?:(?:ال)?نقاط[ \t]+(?:ال)?رئيسية|(?:ال)?وجبات[ \t]+(?:ال)?رئيسية|(?:ال)?نتائج[ \t]+(?:ال)?رئيسية|أهم[ \t]+النقاط|أبرز[ \t]+النقاط(?:[ \t]+الرئيسية)?|(?:ال)?خلاصة|(?:ال)?استنتاجات[ \t]+(?:ال)?رئيسية)[ \t]*[:.]?[ \t]*$/gm, '## أبرز النقاط');

// Links to this site: English links never point at /ar/, Arabic links always do,
// and every page path ends with a slash (the site's canonical form).
function siteLinks(md, arabic) {
  return md.replace(/\]\((?:https?:\/\/(?:www\.)?accez\.cloud)?(\/[^)\s?#]*)([?#][^)\s]*)?\)/gi, (all, p, rest) => {
    let path = p.replace(/^\/ar(?=\/|$)/, '') || '/';
    if (!/\.[a-z0-9]+$/i.test(path) && !path.endsWith('/')) path += '/';
    if (arabic) path = '/ar' + (path === '/' ? '/' : path);
    return '](' + path + (rest || '') + ')';
  });
}
enBody = siteLinks(enBody, false);
arBody = siteLinks(arBody, true);

const body = enBody + '\n\n<!-- AR -->\n\n' + arBody;

// ---- 6. Image search query from the tags (brand names skipped) ----
const BRAND_BLOCKLIST = /airbnb|booking\.com|booking|expedia|accez|whatsapp|mada|sadad|ejar|gastat|zatca|fatoora/i;
let searchQuery = 'hospitality business';
const generic = (Array.isArray(frontmatter.tags) ? frontmatter.tags : []).filter(t => t && !BRAND_BLOCKLIST.test(t));
if (generic.length > 0) searchQuery = generic.slice(0, 2).join(' ').toLowerCase();

return [{
  json: {
    frontmatter,
    body,
    parseProblems,
    droppedKeys,
    articleTitle: frontmatter.title || topicData.topic,
    searchQuery,
    topic: topicData.topic,
    topicSlug: topicData.topicSlug,
    rowNumber: topicData.rowNumber,
    colA: topicData.colA,
    colB: topicData.colB,
    colC: topicData.colC
  }
}];

const stripData = $('Combine English and Arabic').first().json;
const unsplashResponse = $input.first().json;

let hasImage = false;
let imageUrl = '';
let photographerName = '';
let photoUrl = '';
let imageAlt = '';

try {
  if (unsplashResponse && Array.isArray(unsplashResponse.results) && unsplashResponse.results.length > 0) {
    const firstResult = unsplashResponse.results[0];
    if (firstResult.urls && firstResult.urls.regular) {
      imageUrl = firstResult.urls.regular;
      hasImage = true;
      photographerName = (firstResult.user && firstResult.user.name) ? firstResult.user.name : '';
      photoUrl = (firstResult.links && firstResult.links.html) ? firstResult.links.html : '';
      // Alt text must describe THIS photo. Gemini writes its alt before the photo
      // is chosen, so it described a different picture; use Unsplash's own description.
      imageAlt = String(firstResult.alt_description || firstResult.description || '')
        .replace(/\s*[—–]\s*|\s+-\s+/g, ', ') // no dashes as punctuation in site copy
        .replace(/\s+/g, ' ').trim();
    }
  }
} catch (e) { hasImage = false; }

const frontmatter = { ...stripData.frontmatter };
const coverImagePath = hasImage ? '/images/blog/' + stripData.topicSlug + '.jpg' : '/images/blog/pm-default.jpg';
frontmatter.coverImage = coverImagePath;
if (hasImage) {
  frontmatter.coverImageAlt = imageAlt
    ? imageAlt.charAt(0).toUpperCase() + imageAlt.slice(1)
    : 'Cover photo for the article ' + (frontmatter.title || stripData.topic);
  if (photographerName && photoUrl) {
    frontmatter.coverImageCredit = 'Photo by ' + photographerName + ' on Unsplash';
    frontmatter.coverImageCreditUrl = photoUrl;
  }
}
// (No image: Strip node already set the default cover, its alt text, and no credit.)

return [{
  json: {
    frontmatter,
    body: stripData.body,
    parseProblems: stripData.parseProblems,
    articleTitle: stripData.articleTitle,
    topic: stripData.topic,
    topicSlug: stripData.topicSlug,
    rowNumber: stripData.rowNumber,
    colA: stripData.colA,
    colB: stripData.colB,
    colC: stripData.colC,
    imageUrl,
    hasImage,
    coverImagePath,
    imageFilePath: 'public/images/blog/' + stripData.topicSlug + '.jpg',
    photographerName,
    photoUrl
  }
}];

const topicData = $('Find First Pending Topic').first().json;
const sheetRow = {};
sheetRow[topicData.colA] = topicData.topic;
sheetRow[topicData.colB] = 'used';
if (topicData.colC) { sheetRow[topicData.colC] = DateTime.now().toFormat('yyyy-MM-dd'); }
return [{ json: { ...sheetRow, _topic: topicData.topic } }];

// Turns the GitHub listing of content/blog into ONE item for the writing steps:
// - existingSlugs: every post that exists (Quality Gate rejects /blog/ links to anything else)
// - duplicateOf: an existing post this topic repeats (then nothing is written)
// - relatedPostsList: up to 6 existing articles Gemini may link to
// - solution: which solution page the post ends with (property managers or service providers)
// - formatInstruction: which article format to use, so posts do not all share one template
const topicData = $('Find First Pending Topic').first().json;

const files = $input.all()
  .map(item => item.json || {})
  .filter(f => typeof f.name === 'string' && f.name.endsWith('.md'));

// null = the listing failed (see the node's error output); then no /blog/ links are allowed
// and the duplicate check is skipped (GitHub still refuses to overwrite an existing file).
const existingSlugs = files.length > 0 ? files.map(f => f.name.replace(/\.md$/, '')) : null;

// ---------- Words of a title or slug, normalised ----------
const STOP = new Set(('a an and are as at be by for from how in into is it its of on or that the their this to what when where which why with without your you vs versus '
  + 'while going more less make get getting guide tips ways best practices complete ultimate simple step steps '
  + 'create creating manage use using run running set setup new your accez cloud '
  + 'property properties management manager managers managing rental rentals saudi arabia ksa kingdom').split(' '));
const stem = w => w.replace(/ies$/, 'y').replace(/(?<=\w{4})ing$/, '').replace(/(?<=\w{3})(?<!s)s$/, '');
const words = text => String(text).toLowerCase()
  .normalize('NFKD').replace(/[̀-ͯ]/g, '')
  .replace(/['’]/g, '')
  .split(/[^a-z0-9]+/)
  .filter(w => w.length > 2 && !STOP.has(w))
  .map(stem);

// ---------- 1. Duplicate check (slug and title against every existing post) ----------
// Near duplicate = strong word overlap once filler and generic property words are dropped:
// 3 or more shared words with a Jaccard overlap of 0.6 or more, or every word of the
// shorter one shared (3 words or more, or 2 words with an overlap of 0.5 or more),
// or 3 or more shared words with an overlap of 0.75 when only grammar words are dropped.
const topicWords = new Set([...words(topicData.topic), ...words(topicData.topicSlug.replace(/-/g, ' '))]);
const GRAMMAR = new Set('a an and are as at be by for from in into is it its of on or the their this to with your you'.split(' '));
const lightWords = text => String(text).toLowerCase().split(/[^a-z0-9]+/).filter(w => w && !GRAMMAR.has(w)).map(stem);
const topicLight = new Set(lightWords(topicData.topicSlug));
function overlap(slug) {
  const ws = words(slug.replace(/-/g, ' '));
  // Old slugs were cut mid-word at 60 characters ("...-while-goi"): a cut last word
  // matches the topic word it starts.
  if (slug.length >= 55 && ws.length) {
    const last = ws[ws.length - 1];
    const full = [...topicWords].find(w => w !== last && w.startsWith(last));
    if (full) ws[ws.length - 1] = full;
  }
  const own = new Set(ws);
  const shared = [...own].filter(w => topicWords.has(w)).length;
  const union = new Set([...own, ...topicWords]).size;
  // Same check with only grammar words dropped, for titles made mostly of generic words
  // ("How to Create and Manage Properties in Accez.Cloud").
  const lightOwn = new Set(lightWords(slug));
  const lightShared = [...lightOwn].filter(w => topicLight.has(w)).length;
  const lightUnion = new Set([...lightOwn, ...topicLight]).size;
  return {
    slug, shared, jaccard: union ? shared / union : 0, smaller: Math.min(own.size, topicWords.size),
    lightShared, lightJaccard: lightUnion ? lightShared / lightUnion : 0
  };
}
let duplicateOf = null;
let duplicateReason = '';
if (existingSlugs) {
  if (existingSlugs.includes(topicData.topicSlug)) {
    duplicateOf = topicData.topicSlug;
    duplicateReason = 'same URL slug';
  } else {
    const best = existingSlugs.map(overlap)
      .filter(o => (o.shared >= 3 && (o.jaccard >= 0.6 || o.shared === o.smaller))
        || (o.shared >= 2 && o.shared === o.smaller && o.jaccard >= 0.5)
        || (o.lightShared >= 3 && o.lightJaccard >= 0.75))
      .sort((a, b) => b.jaccard - a.jaccard || b.lightJaccard - a.lightJaccard || b.shared - a.shared)[0];
    if (best) {
      duplicateOf = best.slug;
      duplicateReason = Math.max(best.shared, best.lightShared) + ' shared words (overlap '
        + Math.round(Math.max(best.jaccard, best.lightJaccard) * 100) + '%)';
    }
  }
}

// ---------- 2. Related articles Gemini may link to ----------
const candidates = (existingSlugs || [])
  .filter(slug => slug !== topicData.topicSlug)
  .map(slug => ({ slug, score: overlap(slug).shared }))
  .filter(c => c.score > 0)
  .sort((a, b) => b.score - a.score || a.slug.localeCompare(b.slug))
  .slice(0, 6);
const relatedPostsList = candidates.length > 0
  ? candidates.map(c => '- /blog/' + c.slug + '/ (about: ' + c.slug.replace(/-/g, ' ') + ')').join('\n')
  : '(no related articles available: do not link to any /blog/ article)';

// ---------- 3. Matching solution page (the post's closing link) ----------
// Appointment businesses (barbers, salons, spas, coaches, clinics...) -> service provider
// solution; everything else -> property management solution.
const SERVICE_SIGNALS = /\b(barbers?|barbershops?|salons?|spas?|beauty|nails?|coach(es|ing)?|personal trainers?|fitness|gyms?|clinics?|tutors?|groomers?|appointments?|walk[\s-]?ins?|no[\s-]?shows?|service (business|businesses|providers?)|loyalty points?|gift cards?|waitlists?|promo codes?)\b/gi;
const PROPERTY_SIGNALS = /\b(propert(y|ies)|tenants?|landlords?|leases?|rent|rents|rental|rentals|owners?|units?|buildings?|compounds?|hotels?|serviced apartments?|guests?|airbnb|booking\.com|expedia|vacation|short[\s-]term|long[\s-]term|occupancy|portfolios?|developers?|off[\s-]plan|maintenance|work orders?|housekeeping|check[\s-]?ins?)\b/gi;
const count = re => (topicData.topic.match(re) || []).length;
const solution = count(SERVICE_SIGNALS) > count(PROPERTY_SIGNALS) ? 'service-providers' : 'property-managers';
const SOLUTIONS = {
  'property-managers': { name: 'Accez property management solution', nameAr: 'حل أكسيز لإدارة العقارات', readers: 'property managers, owners and operators in Saudi Arabia' },
  'service-providers': { name: 'Accez service provider solution', nameAr: 'حل أكسيز لمقدمي الخدمات', readers: 'owners and managers of appointment businesses (barbers, salons, spas, coaches) in Saudi Arabia' }
};
const solutionPath = '/solutions/' + solution + '/';
const solutionPathAr = '/ar' + solutionPath;

// ---------- 4. Article format ----------
const FORMATS = {
  'how-to': 'HOW-TO GUIDE: after the opening, one short section on what to prepare first, then the steps in order as ### headings under one or two ## sections. Each step heading starts with a verb and names the action for this topic. Finish the body with a section on the mistakes that undo the steps.',
  'checklist': 'CHECKLIST: group the checks into 3 to 5 ## sections by stage or area of this topic. Inside each section, every check is a bullet that starts with a short bold action, followed by one or two sentences on why it matters and how to confirm it is done.',
  'explainer': 'EXPLAINER: answer, in this order, what the subject is, why it matters to operators in Saudi Arabia, how it works in practice (with a worked example), and what the reader has to decide. Each ## heading is a specific statement or question about this topic.',
  'comparison': 'COMPARISON OF APPROACHES: compare 2 or 3 ways of handling this topic (for example in house versus outsourced, manual versus software, monthly versus yearly). Never compare competitors and never name other software products. Include exactly one markdown table comparing the approaches on 4 to 6 criteria, then a section on which approach suits which kind of operator.',
  'glossary': 'GLOSSARY STYLE GUIDE: a short opening, then the key terms of this topic as ### headings grouped under 2 or 3 ## sections; define each term in plain language with an example from operations in Saudi Arabia. End the body with a section showing how the terms fit together in practice.'
};
const ALIASES = { 'how-to': /^how[\s-]*to$|^howto$|^guide$|^step/i, 'checklist': /^check[\s-]*list/i, 'explainer': /^expla/i, 'comparison': /^compar/i, 'glossary': /^gloss/i };
const fromSheet = Object.keys(ALIASES).find(k => ALIASES[k].test(String(topicData.format || '').trim())) || null;
const t = topicData.topic.toLowerCase();
let suggested = /\b(glossary|terms|terminology|jargon|a to z)\b/.test(t) ? 'glossary'
  : /\b(vs\.?|versus|compar\w*|pros and cons|choosing between|which is better|in[\s-]house|outsourc\w*)\b/.test(t) ? 'comparison'
  : /\b(checklist|signs|mistakes|red flags|audit)\b|^\d+\s/.test(t) ? 'checklist'
  : /^(how to|how do|how can)\b|\b(step by step|setting up|set up|getting started|playbook)\b/.test(t) ? 'how-to'
  : /^(what is|what are|why|understanding)\b|\bexplained\b/.test(t) ? 'explainer'
  : null;
if (!suggested) {
  // No signal in the topic: rotate by the slug so consecutive posts do not share one template.
  const rotation = ['how-to', 'checklist', 'explainer', 'comparison'];
  let h = 0;
  for (const ch of topicData.topicSlug) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  suggested = rotation[h % rotation.length];
}
const format = fromSheet || suggested;
const formatInstruction = fromSheet
  ? 'Use this format (chosen by the editor): ' + FORMATS[format]
  : 'Suggested format: ' + FORMATS[format] + '\nUse it unless one of these other formats clearly fits the topic better:\n'
    + Object.keys(FORMATS).filter(k => k !== format).map(k => '- ' + FORMATS[k]).join('\n');

return [{
  json: {
    topic: topicData.topic,
    topicSlug: topicData.topicSlug,
    existingSlugs,
    isDuplicate: duplicateOf !== null,
    duplicateOf,
    duplicateReason,
    relatedSlugs: candidates.map(c => c.slug),
    relatedPostsList,
    relatedPostsListAr: relatedPostsList.replace(/- \/blog\//g, '- /ar/blog/'),
    solution,
    solutionPath,
    solutionPathAr,
    solutionName: SOLUTIONS[solution].name,
    solutionNameAr: SOLUTIONS[solution].nameAr,
    readers: SOLUTIONS[solution].readers,
    format,
    formatSource: fromSheet ? 'sheet' : 'workflow',
    formatInstruction
  }
}];

// The topic repeats an existing post (same slug, or strong word overlap with
// its slug): nothing is written. The status column gets "duplicate: <existing slug>"
// so the row is not picked again. Change the topic and set it back to "pending"
// to write it anyway.
const plan = $('Collect Existing Posts').first().json;
const topicData = $('Find First Pending Topic').first().json;
const row = {};
row[topicData.colA] = topicData.topic;
row[topicData.colB] = 'duplicate: ' + plan.duplicateOf;
if (topicData.colC) { row[topicData.colC] = $now.toFormat('yyyy-MM-dd'); }
return [{ json: row }];

// Step 1 of 2: the English article from Gemini. Stops the run (red execution, the
// topic stays pending) when Gemini returned nothing, so the Arabic step never
// writes from an empty article. Code fences and chatter before the frontmatter are
// removed here so the Arabic step sees the article only.
const raw = $input.first().json.text;
if (!raw || !String(raw).trim()) {
  throw new Error('No content received from Gemini (English article). Check the AI model response.');
}
let text = String(raw).replace(/\r\n/g, '\n').trim();
text = text.replace(/^```[a-zA-Z]*[ \t]*\n/, '').replace(/\n```[ \t]*$/, '').trim();
const fmStart = text.search(/^---[ \t]*$/m);
if (fmStart > 0) text = text.slice(fmStart);
return [{ json: { englishDraft: text } }];

// QUALITY GATE: writes the final markdown file and checks it before anything
// is pushed. Every failed check is listed in `qualityIssues`. If there is any,
// "If Quality Passed" sends the run to the "needs review" branch: nothing is
// pushed to GitHub and the sheet row is marked "needs review: <reasons>".
// The limits below are the only knobs.
const META_TITLE_MAX = 60;
const META_DESCRIPTION_MIN = 100; // the brief asks Gemini for 140 to 155
const META_DESCRIPTION_MAX = 160; // Google and the site cut longer descriptions
const TITLE_MAX = 110;
const MIN_WORDS_EN = 500;
const MIN_WORDS_AR = 400;

const data = $input.first().json;
const fm = data.frontmatter || {};
const body = String(data.body || '');
const plan = $('Collect Existing Posts').first().json;
const existingSlugs = plan.existingSlugs; // null if the GitHub listing failed
const issues = [];
const fail = msg => { if (!issues.includes(msg)) issues.push(msg); };

// ---------- Write the file (one quoting rule for every value) ----------
// Each value is a JSON string, which is also a valid YAML double-quoted
// string, so quotes, colons and backslashes inside a title can never break the frontmatter.
const ORDER = ['title', 'titleAr', 'metaTitle', 'metaTitleAr', 'metaDescription', 'metaDescriptionAr',
  'primaryKeyword', 'excerpt', 'excerptAr', 'date', 'author', 'authorAr', 'coverImage', 'coverImageAlt',
  'coverImageCredit', 'coverImageCreditUrl', 'category', 'categoryAr', 'tags', 'tagsAr'];
const yamlValue = v => Array.isArray(v)
  ? '[' + v.map(x => JSON.stringify(String(x))).join(', ') + ']'
  : JSON.stringify(String(v));
const fmLines = ORDER.filter(k => fm[k] !== undefined && fm[k] !== null).map(k => k + ': ' + yamlValue(fm[k]));
const fileContent = '---\n' + fmLines.join('\n') + '\n---\n\n' + body.trim() + '\n';

// ---------- 1. Frontmatter ----------
for (const p of (data.parseProblems || [])) fail('frontmatter: ' + p);
const REQUIRED = ['title', 'titleAr', 'metaTitle', 'metaTitleAr', 'metaDescription', 'metaDescriptionAr',
  'primaryKeyword', 'excerpt', 'excerptAr', 'date', 'author', 'authorAr', 'coverImage', 'coverImageAlt',
  'category', 'categoryAr', 'tags', 'tagsAr'];
for (const k of REQUIRED) {
  const v = fm[k];
  if (Array.isArray(v) ? v.length === 0 : !String(v == null ? '' : v).trim()) fail('frontmatter: "' + k + '" is missing or empty');
}
for (const k of ['tags', 'tagsAr']) if (fm[k] !== undefined && !Array.isArray(fm[k])) fail('frontmatter: "' + k + '" is not a list');
if (fm.date && !/^\d{4}-\d{2}-\d{2}$/.test(fm.date)) fail('frontmatter: date is not yyyy-MM-dd');
// Re-read what was written: every line must be `key: <valid JSON>`.
const written = fileContent.match(/^---\n([\s\S]*?)\n---\n/);
if (!written) fail('frontmatter: block not written');
else for (const line of written[1].split('\n')) {
  const m = line.match(/^([A-Za-z]\w*): (.*)$/);
  try { if (!m) throw new Error(); JSON.parse(m[2]); } catch (e) { fail('frontmatter: invalid line ' + line.slice(0, 40)); }
}
if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(data.topicSlug || '') || data.topicSlug.length > 60) {
  fail('URL slug "' + (data.topicSlug || '') + '" is empty or invalid (write the topic in English)');
}

// ---------- 2. Lengths ----------
const len = k => String(fm[k] || '').length;
if (len('title') > TITLE_MAX) fail('title is ' + len('title') + ' characters (max ' + TITLE_MAX + ')');
if (len('titleAr') > TITLE_MAX) fail('titleAr is ' + len('titleAr') + ' characters (max ' + TITLE_MAX + ')');
for (const k of ['metaTitle', 'metaTitleAr']) {
  if (len(k) > META_TITLE_MAX) fail(k + ' is ' + len(k) + ' characters (max ' + META_TITLE_MAX + ')');
}
for (const k of ['metaDescription', 'metaDescriptionAr']) {
  if (len(k) && (len(k) < META_DESCRIPTION_MIN || len(k) > META_DESCRIPTION_MAX)) {
    fail(k + ' is ' + len(k) + ' characters (allowed ' + META_DESCRIPTION_MIN + ' to ' + META_DESCRIPTION_MAX + ')');
  }
}

// ---------- 3. Body structure ----------
const markerCount = body.split('<!-- AR -->').length - 1;
if (markerCount !== 1) fail('the <!-- AR --> marker appears ' + markerCount + ' times (must be exactly 1)');
const at = body.indexOf('<!-- AR -->');
const en = at === -1 ? body : body.slice(0, at);
const ar = at === -1 ? '' : body.slice(at + '<!-- AR -->'.length);
const words = s => (s.match(/\S+/g) || []).length;
if (words(en) < MIN_WORDS_EN) fail('English part has only ' + words(en) + ' words');
const arLetters = (ar.match(/[ء-ي]/g) || []).length;
const latinLetters = (ar.match(/[A-Za-z]/g) || []).length;
if (words(ar) < MIN_WORDS_AR || arLetters < 4 * latinLetters) fail('Arabic part is missing, too short or not in Arabic');
// Closing line: the last line of each language links the matching solution page
// (property topics -> /solutions/property-managers/, service businesses ->
// /solutions/service-providers/). It also shows the output was not cut off.
const lastLine = s => (s.trim().split('\n').filter(l => l.trim()).pop() || '');
const linksIn = s => [...s.matchAll(/\]\(([^)\s]+)[^)]*\)/g)].map(m => m[1].replace(/^https?:\/\/(?:www\.)?accez\.cloud(?=\/)/i, ''));
const wantEn = plan.solutionPath;
const wantAr = plan.solutionPathAr;
const endsWith = (s, want) => linksIn(lastLine(s)).some(u => u.replace(/\/?$/, '/') === want);
if (!endsWith(en, wantEn)) {
  fail('English part does not end with a closing line linking ' + wantEn + ' (wrong solution page, or the output was cut off)');
}
if (!endsWith(ar, wantAr)) {
  fail('Arabic part does not end with a closing line linking ' + wantAr + ' (wrong solution page, or the output was cut off)');
}
if (/portal\.accez\.cloud/i.test(body + JSON.stringify(fm))) fail('links to or mentions portal.accez.cloud (posts end with the solution page link instead)');
if (!/^## الأسئلة الشائعة[ \t]*$/m.test(ar)) fail('Arabic FAQ heading is not exactly "## الأسئلة الشائعة"');
if (!/^## أبرز النقاط[ \t]*$/m.test(ar)) fail('Arabic takeaways heading is not exactly "## أبرز النقاط"');
if (/^[ \t]*(```|~~~)/m.test(body)) fail('body contains a code fence');
if (/^(title|titleAr|metaTitle|metaTitleAr|metaDescription|metaDescriptionAr|primaryKeyword|excerpt|excerptAr|date|author|authorAr|coverImage\w*|category|categoryAr|tags|tagsAr)[ \t]*:/m.test(body)) {
  fail('body contains frontmatter (YAML) lines');
}
if (/<\/?[a-zA-Z][^>]*>/.test(body)) fail('body contains raw HTML tags');
if (/!\[[^\]]*\]\(/.test(body)) fail('body contains an image (Gemini cannot know real image URLs)');

// ---------- 3b. Headings must describe their section ----------
// Template headings that every old post repeated (EN and AR variants).
const TEMPLATE_HEADING = /\bdo(?:es)?\s+(?:things\s+)?differently\b|\bwhat\s+(?:actually\s+)?breaks\b|\bdeep\s+dive\b|\bnavigating\s+the\s+saudi(?:\s+arabian)?\s+[\w\s]*landscape\b|بشكل\s+مختلف|ما\s+الذي\s+(?:ينكسر|يتعطل|ينهار|يفسد|يحدث\s+(?:بشكل\s+)?خطأ)|ما\s+(?:ينكسر|يتعطل|ينهار)\s+ولماذا|الغوص\s+العميق|التنقل\s+في\s+(?:ال)?مشهد/i;
const GENERIC_HEADING = /^(?:introduction|overview|conclusion|in\s+conclusion|final\s+thoughts|summary|wrapping\s+up|مقدمة|المقدمة|نظرة\s+عامة|الخلاصة|خلاصة|الخاتمة|خاتمة|ملخص|الملخص|أفكار\s+ختامية)$/i;
for (const h of body.match(/^#{2,4}[ \t]+.*$/gm) || []) {
  const text = h.replace(/^#+[ \t]+/, '').replace(/[*_]/g, '').replace(/[:.؟?!]+$/, '').trim();
  if (TEMPLATE_HEADING.test(text)) fail('uses a template heading instead of one that describes the section: "' + text.slice(0, 60) + '"');
  else if (GENERIC_HEADING.test(text)) fail('uses a generic heading: "' + text + '"');
}

// ---------- 4. Punctuation: no dashes (EN and AR, frontmatter and body) ----------
const noUrls = s => s.replace(/\]\([^)]*\)/g, ']').replace(/https?:\/\/\S+/g, '');
const copy = [ORDER.filter(k => !['coverImage', 'coverImageCreditUrl', 'date'].includes(k))
  .map(k => [].concat(fm[k] || []).join(' ')).join('\n'), body].join('\n');
const proseLines = noUrls(copy).split('\n');
if (proseLines.some(l => /[—–]/.test(l))) fail('uses an em dash or en dash');
if (proseLines.some(l => /\S[ \t]+-[ \t]+\S/.test(l.replace(/^\s*-\s+/, '')))) fail('uses a spaced hyphen " - " as punctuation');

// ---------- 5. Facts and statistics ----------
const all = noUrls(body) + '\n' + [].concat(fm.title, fm.titleAr, fm.metaDescription, fm.metaDescriptionAr, fm.excerpt, fm.excerptAr).join('\n');
if (/\+\s?(400|٤٠٠)(?![\d٠-٩])|(?<![\d٠-٩])(400|٤٠٠)\s?\+|(?<![\d٠-٩])(400|٤٠٠)\s+(booking\s+)?(channels|قناة|قنوات)/i.test(all)) {
  fail('mentions "400+" channels (Accez connects Airbnb, Booking.com and Expedia only)');
}
if (/(?<![\d٠-٩.])(77|٧٧)\s?(%|٪|per\s?cent|بالمائة|في المائة|في المئة)|(%|٪)\s?(77|٧٧)(?![\d٠-٩])/i.test(all)) {
  fail('contains the planted "77%" statistic');
}
const EXTERNAL_LINK = /\]\(https?:\/\/(?!(?:www\.|portal\.)?accez\.cloud)[^)]+\)/i;
const STUDY = /\b(?:a|one|another|recent|new)\s+(?:recent\s+|new\s+)?(?:study|survey)\b|\bstudies\s+(?:show|suggest|find|found|indicate)|\bresearch\s+(?:shows|suggests|finds|found|indicates)\b|\baccording\s+to\s+(?:a|recent|industry)\s+(?:study|survey|research|report)|(?:أظهرت|تشير|وجدت|كشفت|تؤكد)\s+(?:دراسة|الدراسات|دراسات|الأبحاث|أبحاث|استطلاع)|وفق(?:ًا|ا)\s+ل(?:دراسة|استطلاع|بحث)|دراسة\s+حديثة|استطلاع\s+حديث/i;
const PERCENT = /[\d٠-٩]\s?(?:%|٪)|(?:%|٪)\s?[\d٠-٩]|\bper\s?cent\b|بالمائة|في المائة|في المئة/i;
for (const block of body.split(/\n[ \t]*\n/)) {
  if (EXTERNAL_LINK.test(block)) continue; // the source is linked in the same paragraph
  const snippet = block.replace(/\s+/g, ' ').trim().slice(0, 70);
  if (STUDY.test(block)) fail('cites a study or research without linking the source: "' + snippet + '"');
  else if (PERCENT.test(block)) fail('states a percentage without linking the source: "' + snippet + '"');
}

// ---------- 6. Claims about Accez ----------
const ACCEZ = /accez|أكسيز|اكسيز/i;
for (const line of body.split('\n')) {
  if (ACCEZ.test(line) && /[\d٠-٩]\s?(%|٪)|[\d٠-٩][\d٠-٩,.]*\s*\+?\s*(customers|clients|users|operators|companies|عميل|عملاء|مستخدم|شركة|شركات)/i.test(noUrls(line))) {
    fail('states a figure or result about Accez: "' + line.trim().slice(0, 70) + '"');
  }
}
const NOT_OFFERED = /whatsapp|\bejar\b|zatca|fatoora|smart[\s-]?locks?|keyless|tenant\s+screening|credit\s+checks?|background\s+checks?|mobile\s+app|\bAI\b|artificial\s+intelligence|machine\s+learning|\bvrbo\b|\bgdpr\b|on[\s-]?prem|metered|metering|واتساب|واتس\s?اب|منصة\s+إيجار|زاتكا|فاتورة\s+الإلكترونية|الفوترة\s+الإلكترونية|الأقفال\s+الذكية|أقفال\s+ذكية|بدون\s+مفتاح|فحص\s+المستأجرين|التحقق\s+الائتماني|الذكاء\s+الاصطناعي|تطبيق\s+(?:ال)?جوال/i;
// OWNER_DECISIONS.md "never claim" list (2026-10-26), English and Arabic.
const NEVER_CLAIM = new RegExp([
  'whatsapp', 'واتساب', 'واتس\\s?اب',
  '\\bmada\\b', '(?:بطاقات?|بطاقة|شبكة|نظام|مدفوعات|دفع|عبر)\\s+مدى(?![\\u0600-\\u06FF])', 'مدى\\s+(?:و|أو)\\s*(?:apple|آبل|أبل|stc|اس|إس)', 'apple\\s*pay', 'آبل\\s*باي', 'أبل\\s*باي', 'stc\\s*pay', 'اس\\s*تي\\s*سي\\s*باي', 'إس\\s*تي\\s*سي\\s*باي',
  '\\bzatca\\b', 'fatoora', '\\be[\\s-]?invoic\\w*', 'زاتكا', 'هيئة\\s+الزكاة', 'فاتورة\\s+الإلكترونية', 'الفوترة\\s+الإلكترونية', 'الفواتير\\s+الإلكترونية',
  '\\be[\\s-]?sign(?:ing|ature|atures|ed)?\\b', '(?:electronic|digital)\\s+signatures?', 'التوقيع\\s+(?:ال)?(?:إلكتروني|رقمي)', 'توقيع\\s+(?:إلكتروني|رقمي)',
  '(?:tenant|resident|guest)s?\\s+(?:portal|app)', 'بوابة\\s+(?:ال)?(?:مستأجر|مستأجرين|سكان|ضيوف)', 'تطبيق\\s+(?:ال)?(?:مستأجر|مستأجرين|سكان|ضيوف)',
  'booking\\s+engine', 'direct\\s+booking\\s+(?:website|site|engine)', 'website\\s+builder', 'محرك\\s+(?:ال)?حجز', 'منشئ\\s+(?:ال)?مواقع',
  '(?:dynamic|automatic|automated|smart)\\s+pricing', 'التسعير\\s+(?:ال)?(?:ديناميكي|تلقائي|آلي|ذكي)',
  'vendor\\s+(?:directory|marketplace)', 'دليل\\s+(?:ال)?موردين',
  'visitor\\s+(?:management|access|passes?|logs?|module)', 'gate\\s+access', 'إدارة\\s+(?:ال)?زوار', '(?:دخول|تصاريح)\\s+(?:ال)?زوار',
  'smart[\\s-]?locks?', 'keyless', 'الأقفال\\s+الذكية', 'أقفال\\s+ذكية',
  'inspection\\s+(?:checklists?|reports?|app)', '(?:قوائم|قائمة)\\s+(?:ال)?فحص', 'تقارير\\s+(?:ال)?فحص',
  'minimum[\\s-]?stay', 'الحد\\s+الأدنى\\s+(?:ل)?(?:مدة\\s+)?(?:ال)?إقامة',
  'automat\\w*\\s+(?:rent\\s+|payment\\s+)?reminders?', 'auto[\\s-]?reminders?', 'reminders?\\s+(?:are\\s+)?sent\\s+automatically', 'تذكيرات?\\s+(?:تلقائية|آلية)', 'التذكير\\s+(?:ال)?(?:تلقائي|آلي)',
  '\\bejar\\b', 'منصة\\s+إيجار', 'إيجار\\s+الإلكترونية',
  '\\bAI\\b', 'artificial\\s+intelligence', 'الذكاء\\s+الاصطناعي',
  // Pricing details the owner does not want stated (2026-10-27).
  'credit\\s+card', 'بطاقة\\s+(?:ال)?ائتمان', 'launch\\s+discount', '\\d+\\s*%\\s*off\\b', 'خصم\\s+(?:ال)?إطلاق', 'dedicated\\s+account\\s+manager', 'custom\\s+development', 'bulk\\s+(?:data\\s+)?import', 'instant\\s+(?:order\\s+)?confirmation'
].join('|'), 'i');
const BOOK_PROVIDERS = /(tenants?|residents?|guests?)\b[^.\n]{0,80}\bbook\w*\b[^.\n]{0,60}\b(service\s+providers?|providers?|barbers?|salons?|spas?|cleaners?)|(المستأجر|المستأجرين|السكان|النزلاء|الضيوف)[^.\n]{0,80}(يحجز|حجز)[^.\n]{0,60}(مقدمي\s+الخدمات|مزودي\s+الخدمات)/i;
const accezSections = [];
let current = null;
for (const line of body.split('\n')) {
  if (/^##\s/.test(line)) { current = ACCEZ.test(line) ? [line] : null; if (current) accezSections.push(current); continue; }
  if (current) current.push(line);
}
for (const section of accezSections) {
  const text = noUrls(section.join('\n'));
  const hit = text.match(NOT_OFFERED) || text.match(NEVER_CLAIM);
  if (hit) fail('the Accez section claims a feature Accez does not offer ("' + hit[0] + '")');
  if (BOOK_PROVIDERS.test(text)) fail('says tenants or guests book service providers through Accez');
}
// Anywhere else: a sentence that names Accez must not claim an unconfirmed feature
// (OWNER_DECISIONS "never claim" list), nor say anything about Accez and ZATCA.
for (const sentence of noUrls(body).split(/(?<=[.!?؟])\s+|\n+/)) {
  if (!ACCEZ.test(sentence)) continue;
  if (BOOK_PROVIDERS.test(sentence)) fail('says tenants or guests book service providers through Accez');
  const hit = sentence.match(NEVER_CLAIM) || sentence.match(NOT_OFFERED);
  if (hit) fail('claims or discusses an unconfirmed Accez feature ("' + hit[0] + '"): "' + sentence.trim().slice(0, 70) + '"');
}

// ---------- 7. Links ----------
const ALLOWED_PAGES = new Set(['', 'solutions/property-managers', 'solutions/service-providers',
  'pricing/property-managers', 'pricing/service-providers', 'faq', 'blog']);
const VAGUE_ANCHOR = /^(here|click here|this|this article|this post|read more|link|learn more|هنا|اضغط هنا|انقر هنا|اقرأ المزيد)$/i;
for (const m of body.matchAll(/\[([^\]]*)\]\(([^)\s]*)[^)]*\)/g)) {
  const anchor = m[1].trim();
  const url = m[2].trim();
  if (VAGUE_ANCHOR.test(anchor.replace(/[.!؟?]+$/, ''))) fail('link text is not descriptive: "' + anchor + '"');
  if (/^https:\/\/portal\.accez\.cloud\/?$/i.test(url)) continue;
  const own = url.match(/^(?:https?:\/\/(?:www\.)?accez\.cloud)?(\/[^?#]*)?(?:[?#].*)?$/i);
  if (own && (url.startsWith('/') || /^https?:\/\/(www\.)?accez\.cloud/i.test(url))) {
    const path = (own[1] || '/').replace(/^\/ar(?=\/|$)/, '').replace(/^\/+|\/+$/g, '');
    const blog = path.match(/^blog\/([^/]+)$/);
    if (blog) {
      if (!existingSlugs || !existingSlugs.includes(blog[1])) fail('links to an article that does not exist: ' + url);
    } else if (!ALLOWED_PAGES.has(path)) {
      fail('links to an unknown site page: ' + url);
    }
    continue;
  }
  if (!/^https?:\/\//i.test(url)) fail('link is not a full URL or a site path: ' + url);
}

return [{
  json: {
    qualityPassed: issues.length === 0,
    qualityIssues: issues,
    qualityReport: issues.length ? issues.join('; ') : 'all checks passed',
    fileContent,
    contentLength: fileContent.length,
    articleTitle: fm.title || data.topic,
    excerpt: fm.excerpt || '',
    topic: data.topic,
    topicSlug: data.topicSlug,
    rowNumber: data.rowNumber,
    colA: data.colA,
    colB: data.colB,
    colC: data.colC,
    hasImage: data.hasImage === true,
    imageUrl: data.imageUrl,
    coverImagePath: data.coverImagePath,
    imageFilePath: data.imageFilePath,
    photographerName: data.photographerName,
    photoUrl: data.photoUrl
  }
}];

// Runs only when the Unsplash download or the image push to GitHub failed.
// The post then uses the default cover, so it never points at a missing image.
const gate = $('Quality Gate').first().json;
const DEFAULT_COVER = '/images/blog/pm-default.jpg';
const DEFAULT_ALT = 'A row of suburban houses under a clear blue sky';

const end = gate.fileContent.indexOf('\n---\n', 4); // end of the frontmatter block
const head = gate.fileContent.slice(0, end)
  .split('\n')
  .filter(line => !/^coverImageCredit(Url)?: /.test(line))
  .map(line => line.startsWith('coverImage: ') ? 'coverImage: ' + JSON.stringify(DEFAULT_COVER)
    : line.startsWith('coverImageAlt: ') ? 'coverImageAlt: ' + JSON.stringify(DEFAULT_ALT)
    : line)
  .join('\n');
const fileContent = head + gate.fileContent.slice(end);

return [{
  json: {
    fileContent,
    coverImagePath: DEFAULT_COVER,
    // GitHub puts the error message in `error` as text; HTTP Request puts an object there.
    imageError: (e => !e ? 'image step failed' : typeof e === 'string' ? e : (e.message || JSON.stringify(e)))($input.first().json.error)
  }
}];

// The post failed "Quality Gate": nothing was pushed. Mark the row so it is
// not picked again, with the reasons, for a person to look at.
// To retry the topic later, set its status back to "pending".
const gate = $('Quality Gate').first().json;
const topicData = $('Find First Pending Topic').first().json;
const row = {};
row[topicData.colA] = topicData.topic;
row[topicData.colB] = ('needs review: ' + gate.qualityIssues.join('; ')).slice(0, 1000);
if (topicData.colC) { row[topicData.colC] = $now.toFormat('yyyy-MM-dd'); }
return [{ json: row }];
